import { createElementWithClass } from '../../../utils/helpers';
import { OptionsItemFactory } from './options-item-factory';
import './options-renderer.css';
export class OptionsRenderer {
    constructor() {
        this._optionsList = createElementWithClass('ul', [
            'app__options-list',
            'flex',
        ]);
    }
    get optionsList() {
        return this._optionsList;
    }
    renderOptionsList(optionsArray) {
        this.optionsList.replaceChildren();
        optionsArray.forEach((option) => this.optionsList.append(OptionsItemFactory.createItem(option)));
    }
    renderOption(option) {
        this.optionsList.append(OptionsItemFactory.createItem(option));
    }
}
